#!/usr/bin/env python3
"""Export the numbered assumptions (and where each is enforced) to notes/assumptions.md.

Usage: uv run scripts/export_assumptions.py   (or `make assumptions`)
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from preop_triage.assumptions import ASSUMPTIONS, IMPLEMENTED_IN  # noqa: E402


def render() -> str:
    lines = [
        "# Assumptions (A1–A19)",
        "",
        "Source of truth: `preop_triage/assumptions.py`. Generated by `make assumptions`; "
        "`tests/test_assumptions.py` fails if this file is stale or if a named function no longer exists.",
        "Each check in the evidence packet cites the IDs it relied on, and `assumptions_applied` lists the ones",
        "exercised for the case, so a reviewer can disagree with an interpretation rather than with the system.",
        "",
    ]
    for aid, text in ASSUMPTIONS.items():
        where = ", ".join(f"`{t.removeprefix('preop_triage.')}`" for t in IMPLEMENTED_IN[aid])
        lines += [f"**{aid}.** {text}  ", f"*Enforced in:* {where}", ""]
    return "\n".join(lines)


def main() -> None:
    out = ROOT / "notes" / "assumptions.md"
    out.write_text(render())
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
